class VarianceSnapshots:
    """Developer tool: paints the run-variance screens (patch-notes drafts, the HUD strip with chips and the news ticker,
hover cards, pause menu seed, end screen) offscreen into PNGs, without opening a window.
java -Djava.awt.headless=true -cp build:lib/acm.jar lindefense.ui.VarianceSnapshots <dir>."""
    def __init__(self):
        pass
    @staticmethod
    def snap(c, dir_, name):
        img = BufferedImage(Ui.W, Ui.H, BufferedImage.TYPE_INT_ARGB)
        g = img.create_graphics()
        Cyber.quality(g)
        c.paint(g)
        g.dispose()
        ImageIO.write(img, 'png', _j.File(dir_, _j.cat(name, '.png')))
    @staticmethod
    def frames(s, n):
        for i in range(n):
            s.frame(0.05)
    @staticmethod
    def main(args):
        """Writes the snapshots into args[0] (default snapshots)."""
        _j.set_property('lindefense.nosound', 'true')
        dir_ = _j.File((args[0] if (len(args) > 0) else 'snapshots'))
        dir_.mkdirs()
        g = Game(maps.create(2), variance.seed_parse('K3X9QZ'), Difficulty.ON)
        g.get_variance().enable()
        s = GameScreen(None, g)
        VarianceSnapshots.frames(s, 12)
        VarianceSnapshots.snap(s, dir_, 'v01_draft_launch')
        s.mouse_moved(600, 560)
        VarianceSnapshots.frames(s, 6)
        VarianceSnapshots.snap(s, dir_, 'v01b_draft_hover')
        s.pick_patch_note(1)
        g.get_variance().grant(PatchNote.CONTEXT_WINDOW)
        g.get_variance().grant(PatchNote.SYNTHETIC_DATA)
        g.add_cash(6000, None)
        spots = [Vec(380, 300), Vec(700, 250), Vec(460, 520), Vec(820, 660), Vec(300, 700)]
        types = [TowerType.GPT, TowerType.CLAUDE, TowerType.PERPLEXITY, TowerType.DEEPSEEK, TowerType.GEMINI]
        for i in range(len(spots)):
            g.place_tower(types[i], TestKit.buildable_near(g, spots[i], 200))
        g.get_variance().force_news(BreakingNews.GPU_SHORTAGE, (-1))
        s.mouse_moved(5, 990)
        VarianceSnapshots.frames(s, 70)
        VarianceSnapshots.snap(s, dir_, 'v02_strip_news_prep')
        g.start_next_wave()
        for i in range(60 * 5):
            g.step(Game.DT)
            if _j.imod(i, 3) == 0:
                s.frame((Game.DT * 3))
        VarianceSnapshots.snap(s, dir_, 'v03_strip_live_wave')
        s.mouse_moved(112, (Ui.WORLD_Y + 12))
        VarianceSnapshots.frames(s, 2)
        VarianceSnapshots.snap(s, dir_, 'v04_chip_hover')
        s.mouse_moved(760, (Ui.WORLD_Y + 12))
        VarianceSnapshots.frames(s, 2)
        VarianceSnapshots.snap(s, dir_, 'v05_news_hover')
        s.mouse_moved(5, 990)
        while g.get_wave() < 19:
            g.get_wave_manager().start_next_wave()
            g.get_wave_manager().end_wave()
        g.get_enemy_manager().clear()
        g.get_wave_manager().can_start_next_wave()
        VarianceSnapshots.frames(s, 12)
        VarianceSnapshots.snap(s, dir_, 'v06_draft_wave20')
        s.pick_patch_note(0)
        VarianceSnapshots.frames(s, 4)
        g.get_variance().force_news(BreakingNews.SERVER_OUTAGE, 1)
        g.start_next_wave()
        g.get_enemy_manager().spawn(EnemyType.BELLARMINE_COLLEGE_PREP, None, 0, 300)
        for i in range(60 * 3):
            g.step(Game.DT)
            if _j.imod(i, 3) == 0:
                s.frame((Game.DT * 3))
        VarianceSnapshots.snap(s, dir_, 'v07_boss_dock_with_strip')
        s.open_menu()
        VarianceSnapshots.frames(s, 3)
        VarianceSnapshots.snap(s, dir_, 'v08_pause_seed')
        s.escape_pressed()
        VarianceSnapshots.frames(s, 2)
        e = g.get_enemy_manager().spawn(EnemyType.STATIC_ARRAY, None, 0, 100)
        g.lose_lives(g.get_lives(), e)
        for i in range(60 * 3):
            g.step(Game.DT)
        VarianceSnapshots.frames(s, 12)
        VarianceSnapshots.snap(s, dir_, 'v09_defeat_with_notes')
        seed = 0
        none = _j.ArrayList()
        while not ((PatchNote.CONTEXT_WINDOW in RunVariance.offer_for(seed, 1, none)) and (PatchNote.ATTENTION in RunVariance.offer_for(seed, 1, none))):
            seed += 1
        lg = Game(maps.create(5), seed, Difficulty.O1)
        lg.get_variance().enable()
        ls = GameScreen(None, lg)
        VarianceSnapshots.frames(ls, 12)
        VarianceSnapshots.snap(ls, dir_, 'v11_draft_long_titles')
        off = Game(maps.create(2), 7)
        so = GameScreen(None, off)
        VarianceSnapshots.frames(so, 6)
        VarianceSnapshots.snap(so, dir_, 'v10_variance_off')
        print(_j.s(_j.cat('snapshots written to ', dir_.get_absolute_path())))
        sys.exit(0)


